let integrationRun=null;
function stopIntegrationWorkspace(){if(integrationRun){clearTimeout(integrationRun.timer);integrationRun.worker.terminate();integrationRun=null;}const run=document.getElementById('it-run'),stop=document.getElementById('it-stop');if(run)run.disabled=false;if(stop)stop.disabled=true;}
function integrationDraftKey(){return 'web-talim:integration:'+activeData().assignment.draftId;}
function renderIntegrationAssignment(data){
 const a=data.assignment,panel=document.createElement('section');panel.id='panel5';panel.hidden=true;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab5');
 panel.innerHTML=`<h2>Amaliy mashg‘ulot</h2><p>${integrationEscape(a.task)}</p><h3>Bajarish tartibi</h3><ol>${a.steps.map(x=>`<li>${integrationEscape(x)}</li>`).join('')}</ol><p class="notice">${a.mode==='js'?'Sof JavaScript mashqi. ▶ Run kodni brauzerning alohida Worker muhitida bajaradi. console.log va assert(condition, message) mavjud. DOM, Node modullari va haqiqiy HTTP server bu oynada ishlamaydi.':a.mode==='local'?'Bu topshiriq yuklab olinadigan loyihada, lokal Node 24, terminal yoki brauzerda bajariladi. Docker va Playwright faqat tegishli dars uchun ixtiyoriy. Bu maydon hosting yoki serverni ishga tushirmaydi.':'Bu tahlil va dalil topshirig‘i. Hisobot yoki sxema tayyorlang; matnni dastur sifatida bajarish talab etilmaydi.'}</p><h3>Kutiladigan natija</h3><p>${integrationEscape(a.expected)}</p><label class="lab-label" for="it-code">${a.mode==='js'?'JavaScript kodi':a.mode==='local'?'Lokal buyruqlar yoki kod parchasi':'Sxema va tekshiruv jadvali'}</label><textarea id="it-code" class="lab-editor" spellcheck="false"></textarea><div class="lab-actions">${a.mode==='js'?'<button class="cta" id="it-run" type="button" onclick="runIntegrationJS()">▶ Run — kodni bajarish</button><button class="retry" id="it-stop" type="button" onclick="stopIntegrationJS()" disabled>To‘xtatish</button>':''}<button class="retry" type="button" onclick="resetIntegrationCode()">Namunani tiklash</button><button class="retry" type="button" onclick="downloadIntegrationCode()">Kodni yuklab olish ↓</button></div>${a.mode==='js'?'<p id="it-status" role="status">Kodni yozib ▶ Run bosing.</p><pre id="it-output" class="lesson-code" aria-live="polite"></pre><p class="muted">5 soniyalik chegara; konsolda ko‘pi bilan 100 satr. Run faqat yozilgan kod natijasini beradi, topshiriqning barcha talablarini avtomatik baholamaydi.</p>':''}<h3>Tekshirish mezonlari</h3>${a.criteria.map(x=>`<label class="option"><input type="checkbox" class="it-check"> ${integrationEscape(x)}</label>`).join('')}<label class="lab-label" for="it-report">Hisobot — muhit, qadam, natija, xato va xulosa</label><textarea id="it-report" class="lab-editor" spellcheck="false"></textarea><p class="muted" id="it-save" role="status">Kod va hisobot shu brauzerda saqlanadi. Amaliy ishni o‘qituvchi dalil asosida tekshiradi.</p><div class="lab-actions"><button class="retry" type="button" onclick="downloadIntegrationReport()">Hisobotni yuklab olish ↓</button><button class="cta" type="button" onclick="openResource(3)">Testga o‘tish →</button></div><p><a href="materials/m8-integration-loyiha.zip" download>Frontend, API, SQLite, testlar va yo‘riqnoma — loyiha ZIP ↓</a></p>`;
 document.querySelector('.article').appendChild(panel);let saved={};try{saved=JSON.parse(localStorage.getItem(integrationDraftKey())||'{}');}catch(e){}
 document.getElementById('it-code').value=saved.code??a.code;document.getElementById('it-report').value=saved.report??'';panel.querySelectorAll('.it-check').forEach((x,i)=>x.checked=!!saved.checks?.[i]);panel.querySelectorAll('textarea,input').forEach(x=>x.addEventListener('input',saveIntegrationWork));
}
function saveIntegrationWork(){try{localStorage.setItem(integrationDraftKey(),JSON.stringify({code:document.getElementById('it-code').value,report:document.getElementById('it-report').value,checks:[...document.querySelectorAll('.it-check')].map(x=>x.checked)}));document.getElementById('it-save').textContent='Shu brauzerda saqlandi; boshqa qurilmaga avtomatik ko‘chmaydi.';}catch(e){document.getElementById('it-save').textContent='Saqlash mavjud emas. Kod va hisobotni yuklab oling.';}}
function integrationDownload(text,name){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function downloadIntegrationCode(){integrationDownload(document.getElementById('it-code').value,`m8-${currentLesson}.${activeData().assignment.mode==='js'?'js':'txt'}`);}
function downloadIntegrationReport(){integrationDownload(document.getElementById('it-report').value,`m8-${currentLesson}-hisobot.txt`);}
function resetIntegrationCode(){stopIntegrationWorkspace();document.getElementById('it-code').value=activeData().assignment.code;const out=document.getElementById('it-output');if(out)out.textContent='';saveIntegrationWork();}
function stopIntegrationJS(){stopIntegrationWorkspace();document.getElementById('it-status').textContent='Bajarish to‘xtatildi.';}
function runIntegrationJS(){
 if(activeData().assignment.mode!=='js')return;stopIntegrationWorkspace();saveIntegrationWork();const code=document.getElementById('it-code').value;
 if(code.length>50000){document.getElementById('it-status').textContent='Kod 50 000 belgidan oshmasin.';return;}
 document.getElementById('it-output').textContent='';document.getElementById('it-run').disabled=true;document.getElementById('it-stop').disabled=false;document.getElementById('it-status').textContent='Kod bajarilmoqda…';
 let worker;try{worker=new Worker('integration-js-worker.js');}catch(e){stopIntegrationWorkspace();document.getElementById('it-status').textContent='Muhitni ochib bo‘lmadi: '+e.message;return;}
 const finish=message=>{stopIntegrationWorkspace();document.getElementById('it-status').textContent=message;};const timer=setTimeout(()=>finish('5 soniyalik chegara tugadi. Sikl yoki kutishni tekshiring.'),5000);integrationRun={worker,timer};
 worker.onerror=()=>finish('JavaScript muhitini yuklash xatosi. Lokal loyihadan foydalaning.');
 worker.onmessage=event=>{if(integrationRun?.worker!==worker)return;const d=event.data;if(!['done','error'].includes(d.type))return;document.getElementById('it-output').textContent=(d.lines||[]).join('\n')+(d.type==='error'?'\nXato: '+d.message:'');finish(d.type==='done'?`Bajarildi. ${d.checks} ta assert tekshiruvi o‘tdi.`:'Kod xatosi. Konsoldagi izohni tekshiring.');};worker.postMessage({code});
}
